insert into public.closure_extras (id, payload) values
  ('masarykova', '{"title": "Rekonstrukce Masarykovy ulice", "sub": "Úsek Rokycanská – Těšínská · od 29. 6. 2026 · 115 mil. Kč bez DPH", "phases": [["Příprava (kácení stromů)", "do 6/2026", "done"], ["1. etapa: Rokycanská – Těšínská", "od 29. 6. 2026", "now"], ["2. etapa", "navazuje na 1.", ""], ["Dokončení", "2027 (orientačně)", ""]], "means": ["<b>Co se rekonstruuje:</b> vodovod a kanalizace, vozovka, chodníky a cyklostezky, světelná signalizace.", "<b>Řidiči:</b> úsek úplně uzavřen, objížďka přes Rokycanskou → Jateční → Těšínskou.", "<b>MHD:</b> linky 29, 30, N3 a N6 obousměrný odklon stejnou trasou — v uzavřeném úseku se nezastavuje.", "<b>Pěší a rezidenti:</b> přístup k domům zachován.", "<b>Stromy:</b> v úseku už šly v březnu 2026, na podzim přijdou nové."], "objizdka": ["<b>Auta:</b> obousměrný odklon přes Rokycanskou → Jateční → Těšínskou.", "<b>Cyklisté:</b> po objízdné trase s auty (cyklostezka v rekonstruovaném úseku není průjezdná).", "<b>Doprava do Doubravky z centra:</b> zachována přes Rokycanskou; od Jateční sjezd do obytné zóny."], "mhd": ["Linky 29, 30, N3 a N6 obousměrně přes Rokycanskou → Jateční → Těšínskou.", "V uzavřeném úseku se autobusy nezastavují — žádná zastávka v úseku není."], "mhdInfo": {"summary": "Linky 29, 30, N3, N6 obousměrný odklon · žádné zastávky v úseku", "reroutes": [{"lines": ["29", "30"], "mode": "bus", "via": "obousměrně přes Rokycanskou → Jateční → Těšínskou", "note": "denní spoje"}, {"lines": ["N3", "N6"], "mode": "night", "via": "obousměrně přes Rokycanskou → Jateční → Těšínskou", "note": "noční spoje"}], "notes": ["V uzavřeném úseku se autobusy nezastavují — žádná zastávka tu není.", "Spoje pojedou po objížďce přímo, bez vkládání zastávek."], "sourceUrl": "https://www.pmdp.cz/systransport/63/6/4279/zahajeni-rekonstrukce-masarykovy-ulice-odklon-linek-29-30-n3-n6-od-29-6-2026/", "sourceLabel": "PMDP (15. 6. 2026)"}, "source": {"label": "plzen.eu — Centrum Doubravky čeká proměna", "url": "https://plzen.eu/o-meste/aktuality/aktuality-z-mesta/centrum-doubravky-ceka-promena-masarykova-ulice-bude-bezpecnejsi-i-privetivejsi/"}, "keyNumbers": [{"value": "115", "unit": "mil. Kč", "label": "Bez DPH", "tone": "blue"}, {"value": "~1", "unit": "rok", "label": "Trvání"}, {"value": "4", "label": "MHD linek", "tone": "alert"}, {"value": "0", "label": "Přesun. zastáv."}], "scope": [{"icon": "💧", "label": "Vodovod"}, {"icon": "🚿", "label": "Kanalizace"}, {"icon": "🛣️", "label": "Vozovka"}, {"icon": "👞", "label": "Chodníky"}, {"icon": "🚲", "label": "Cyklostezky"}, {"icon": "🚦", "label": "Signalizace"}], "detourSteps": ["Doubravka", "Rokycanská", "Jateční", "Těšínská", "centrum"]}'::jsonb),
  ('americka', '{"title": "Rekonstrukce Americké třídy", "sub": "440 m centrum · 3 etapy · do 11. 8. 2026 · 36 mil. Kč", "phases": [["1. etapa — Goethova–Jungmannova (úplná uzavírka)", "od 11. 5. 2026", "now"], ["2. etapa — Goethova–V Šipce (úplná), V Šipce–Klatovská (jednosměr)", "od 22. 6. 2026", ""], ["3. etapa — Anglické nábřeží–V Šipce + okružní křižovatka", "od 23. 7. 2026", ""], ["Dokončení", "11. 8. 2026", ""]], "objizdka": ["<b>1. etapa:</b> osobní doprava od Klatovské průjezdná do ulic Škroupova a Jungmannova; okružní křižovatka zůstává průjezdná.", "<b>2. etapa (od 22. 6.):</b> pro osobní dopravu uzavřen úsek Klatovská – Škroupova, umožněn jen průjezd z ulice V Šipce ke Klatovské.", "<b>3. etapa (od 23. 7.):</b> úplná uzavírka okružní křižovatky Americká – Goethova – Prokopova."], "mhd": ["1.–2. etapa: část MHD vedena přes Anglické nábřeží, Kopeckého a Smetanovy sady, část ulicemi Prokopova a U Trati.", "3. etapa: část MHD pojede ulicemi Mikulášská a U Trati."], "keyNumbers": [{"value": "36", "unit": "mil. Kč", "label": "Rozpočet", "tone": "blue"}, {"value": "440", "unit": "m", "label": "Délka úseku"}, {"value": "3", "label": "Etapy"}, {"value": "3", "unit": "měs", "label": "Trvání", "tone": "alert"}], "scope": [{"icon": "🛣️", "label": "Vozovka"}, {"icon": "👞", "label": "Chodníky"}, {"icon": "🌳", "label": "Veř. prostor"}, {"icon": "♿", "label": "Bezbariér."}], "detourSteps": ["centrum", "Anglické nábřeží", "Kopeckého", "Smetanovy sady", "Prokopova", "U Trati"], "source": {"label": "Magistrát města Plzně — aktuality", "url": "https://plzen.eu/o-meste/aktuality/aktuality-z-mesta/rekonstrukce-americke-vstoupi-od-22-cervna-do-2-etapy-rozsiri-se-dopravni-opatreni/"}}'::jsonb),
  ('domazlicka', '{"title": "Oprava Domažlické ulice (ŘSD, I/26)", "sub": "Úsek Tylova – mosty přes trať · 1. 7. – konec srpna 2026 · 24,56 mil. Kč", "phases": [["Příprava", "do 6/2026", "done"], ["1. etapa: protisměrný režim", "od 1. 7. 2026", ""], ["Další etapy navazují", "léto 2026", ""], ["Dokončení", "konec srpna 2026", ""]], "means": ["<b>Řidiči:</b> částečná uzavírka — provoz sveden do protisměrného jízdního pásu, práce po navazujících etapách.", "<b>Délka úseku:</b> přibližně 1,2 km (silnice I/26 od křižovatky s Tylovou po mosty přes trať na Domažlice).", "<b>MHD a chodci:</b> součástí jsou úpravy autobusových zastávek a chodníků."], "keyNumbers": [{"value": "24,56", "unit": "mil. Kč", "label": "S DPH", "tone": "blue"}, {"value": "~2", "unit": "měs", "label": "Trvání"}, {"value": "1,2", "unit": "km", "label": "Délka úseku"}, {"value": "½", "label": "Pásu uzavřeno", "tone": "alert"}], "scope": [{"icon": "🛣️", "label": "Vozovka"}, {"icon": "🧱", "label": "Zesílení"}, {"icon": "👞", "label": "Chodníky"}, {"icon": "🚌", "label": "Zastávky"}, {"icon": "🚧", "label": "Dělicí pás"}, {"icon": "💧", "label": "Odvodnění"}], "source": {"label": "Magistrát města Plzně — aktuality", "url": "https://plzen.eu/o-meste/aktuality/aktuality-z-mesta/reditelstvi-silnic-a-dalnic-behem-letnich-prazdnin-opravi-usek-domazlicke-ulice-v-plzni/"}}'::jsonb),
  ('28-rijna', '{"title": "Rekonstrukce ulice 28. října (Bílá Hora)", "sub": "Silnice II/231 · 4. 5. – 20. 12. 2026 · ve dvou etapách · 130 mil. Kč", "keyNumbers": [{"value": "130", "unit": "mil. Kč", "label": "Cena celkem", "tone": "blue"}, {"value": "~7", "unit": "měs", "label": "Trvání"}, {"value": "2", "label": "Etapy"}, {"value": "1", "label": "Točna přesun.", "tone": "alert"}], "scope": [{"icon": "💧", "label": "Vodovod"}, {"icon": "🚿", "label": "Kanalizace"}, {"icon": "🛣️", "label": "Vozovka"}, {"icon": "🔥", "label": "Plynovod"}, {"icon": "🚌", "label": "Zálivy"}, {"icon": "🚦", "label": "Signalizace"}], "detourSteps": ["centrum", "Jateční", "Chrástecká", "Mohylová", "Masarykova", "II/233", "Chrást → Dolany → Zruč"], "phases": [["1. etapa — úsek po křižovatku Nad Řekou", "od 4. 5. 2026", "now"], ["2. etapa — Nad Řekou → Zručská cesta", "navazuje", ""], ["Dokončení", "20. 12. 2026", ""]], "objizdka": ["<b>Rezidenti Bílé Hory (1. etapa):</b> obousměrně přes Zručskou cestu.", "<b>Rezidenti (2. etapa):</b> přes ulici Nad Řekou; Zručská cesta obousměrně vyblokována až ke křižovatce s 28. října.", "<b>Ostatní i nákladní doprava:</b> z Jateční přes Chrásteckou, Mohylovou a Masarykovu po II/233 na Chrást a dál po II/180 přes Dolany do Zruče-Sence."], "mhd": ["Provoz autobusů zachován; průjezd autobusů a IZS uzavírkou umožněn.", "Točna Bílá Hora dočasně přesunuta do ulice Nad Řekou.", "Objízdné trasy autobusů dočasně přes ulice Senecká a Nad Řekou.", "Pro chodce vyznačeny bezpečné koridory podél stavby."], "mhdInfo": {"summary": "Bus zachován · točna přesunuta · objížďka pro autobusy", "reroutes": [{"mode": "bus", "via": "Senecká → Nad Řekou", "note": "dočasná objízdná trasa autobusů"}], "tempStops": [{"name": "Bílá Hora (točna)", "where": "ulice Nad Řekou", "note": "dočasné přesunutí točny"}], "notes": ["Průjezd autobusů a vozidel IZS uzavírkou je umožněn.", "Pro chodce jsou vyznačeny bezpečné koridory podél stavby."], "sourceUrl": "https://www.pmdp.cz/cz/informace-o-preprave/zmeny-v-doprave/", "sourceLabel": "PMDP — Změny v dopravě"}, "source": {"label": "Magistrát města Plzně — aktuality", "url": "https://plzen.eu/o-meste/aktuality/aktuality-z-mesta/v-kvetnu-odstartuje-dalsi-etapa-opravy-silnice-na-bile-hore-uplna-uzavirka-zrychli-prace-o-dva-mesice/"}}'::jsonb)
